function windowsAtAverage(arr: number[], k: number, threshold: number): number {
  let count = 0;
  for (let s = 0; s + k <= arr.length; s++) {
    let sum = 0;
    for (let i = s; i < s + k; i++) sum += arr[i];
    if (sum >= k * threshold) count++;
  }
  return count;
}

