function windowsAtAverage(arr: number[], k: number, threshold: number): number {
  const target = k * threshold;
  let sum = 0, count = 0;
  for (let i = 0; i < arr.length; i++) {
    sum += arr[i];
    if (i >= k) sum -= arr[i - k];
    if (i >= k - 1 && sum >= target) count++;
  }
  return count;
}

